-- Grace initial schema, version 1 (mysql). Generated by npm run db:schema.
-- Use a dedicated database with utf8mb4 encoding.

CREATE TABLE IF NOT EXISTS schema_migrations (
  version INTEGER PRIMARY KEY,
  applied_at VARCHAR(32) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS workspaces (
  id VARCHAR(64) PRIMARY KEY,
  name VARCHAR(120) NOT NULL,
  slug VARCHAR(120) NOT NULL UNIQUE,
  created_at VARCHAR(32) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS users (
  id VARCHAR(64) PRIMARY KEY,
  email VARCHAR(254) NOT NULL UNIQUE,
  name VARCHAR(120) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  color VARCHAR(20) NOT NULL,
  capacity INTEGER NOT NULL DEFAULT 40,
  created_at VARCHAR(32) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS memberships (
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  role VARCHAR(20) NOT NULL,
  PRIMARY KEY (workspace_id,user_id),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS sessions (
  id VARCHAR(64) PRIMARY KEY,
  user_id VARCHAR(64) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  refresh_hash VARCHAR(128) NOT NULL UNIQUE,
  expires_at VARCHAR(32) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS invites (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  email VARCHAR(254) NOT NULL,
  role VARCHAR(20) NOT NULL,
  token_hash VARCHAR(128) NOT NULL UNIQUE,
  expires_at VARCHAR(32) NOT NULL,
  accepted_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(workspace_id) REFERENCES workspaces(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS projects (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  `key` VARCHAR(10) NOT NULL,
  description TEXT NOT NULL,
  color VARCHAR(20) NOT NULL,
  icon VARCHAR(30) NOT NULL,
  lead_id VARCHAR(64) NOT NULL,
  template VARCHAR(20) NOT NULL,
  visibility VARCHAR(20) NOT NULL DEFAULT 'workspace',
  favorite INTEGER NOT NULL DEFAULT 0,
  next_number INTEGER NOT NULL DEFAULT 1,
  archived_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  UNIQUE(workspace_id,`key`),
  FOREIGN KEY (workspace_id) REFERENCES workspaces(id),
  FOREIGN KEY (lead_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS project_members (
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  role VARCHAR(20) NOT NULL,
  PRIMARY KEY(project_id,user_id),
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS statuses (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  name VARCHAR(80) NOT NULL,
  category VARCHAR(20) NOT NULL,
  color VARCHAR(20) NOT NULL,
  position INTEGER NOT NULL,
  wip_limit INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (project_id) REFERENCES projects(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS sprints (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  goal TEXT NOT NULL,
  state VARCHAR(20) NOT NULL,
  start_date VARCHAR(32) NOT NULL,
  end_date VARCHAR(32) NOT NULL,
  committed_points INTEGER NOT NULL DEFAULT 0,
  completed_points INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY(project_id) REFERENCES projects(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS issues (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  number INTEGER NOT NULL,
  `key` VARCHAR(32) NOT NULL,
  summary VARCHAR(255) NOT NULL,
  description TEXT NOT NULL,
  type VARCHAR(20) NOT NULL,
  status_id VARCHAR(64) NOT NULL,
  priority VARCHAR(20) NOT NULL,
  assignee_id VARCHAR(64),
  reporter_id VARCHAR(64) NOT NULL,
  parent_id VARCHAR(64),
  sprint_id VARCHAR(64),
  labels TEXT NOT NULL,
  story_points INTEGER NOT NULL DEFAULT 0,
  due_date VARCHAR(32) NOT NULL,
  start_date VARCHAR(32) NOT NULL,
  `rank` REAL NOT NULL,
  flagged INTEGER NOT NULL DEFAULT 0,
  carry_over INTEGER NOT NULL DEFAULT 0,
  version INTEGER NOT NULL DEFAULT 1,
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  deleted_at VARCHAR(32),
  UNIQUE(project_id,number),
  UNIQUE(workspace_id,`key`),
  FOREIGN KEY (project_id) REFERENCES projects(id),
  FOREIGN KEY(status_id) REFERENCES statuses(id),
  FOREIGN KEY(assignee_id) REFERENCES users(id),
  FOREIGN KEY(reporter_id) REFERENCES users(id),
  FOREIGN KEY(parent_id) REFERENCES issues(id),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS comments (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  body TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  edited_at VARCHAR(32),
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(author_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS history (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  actor_id VARCHAR(64) NOT NULL,
  field VARCHAR(80) NOT NULL,
  old_value TEXT NOT NULL,
  new_value TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(actor_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS worklogs (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  minutes INTEGER NOT NULL,
  note TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS attachments (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  uploader_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  path VARCHAR(128) NOT NULL,
  mime VARCHAR(120) NOT NULL,
  size INTEGER NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS issue_links (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  source_id VARCHAR(64) NOT NULL,
  target_id VARCHAR(64) NOT NULL,
  type VARCHAR(30) NOT NULL,
  UNIQUE(source_id,target_id,type),
  FOREIGN KEY(source_id) REFERENCES issues(id),
  FOREIGN KEY(target_id) REFERENCES issues(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS watchers (
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  PRIMARY KEY(issue_id,user_id),
  FOREIGN KEY(issue_id) REFERENCES issues(id),
  FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS notifications (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64),
  title VARCHAR(255) NOT NULL,
  body TEXT NOT NULL,
  read_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS pages (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64),
  title VARCHAR(255) NOT NULL,
  content TEXT NOT NULL,
  icon VARCHAR(30) NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(author_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS page_versions (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  page_id VARCHAR(64) NOT NULL,
  title VARCHAR(255) NOT NULL,
  content TEXT NOT NULL,
  version INTEGER NOT NULL,
  author_id VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(page_id) REFERENCES pages(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS saved_views (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  query TEXT NOT NULL,
  owner_id VARCHAR(64) NOT NULL,
  sharing VARCHAR(20) NOT NULL,
  FOREIGN KEY(owner_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS standups (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  user_id VARCHAR(64) NOT NULL,
  yesterday TEXT NOT NULL,
  today TEXT NOT NULL,
  blockers TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS risks (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64),
  title VARCHAR(255) NOT NULL,
  severity VARCHAR(20) NOT NULL,
  state VARCHAR(20) NOT NULL,
  owner_id VARCHAR(64) NOT NULL,
  created_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS audit_log (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  actor_id VARCHAR(64) NOT NULL,
  action VARCHAR(80) NOT NULL,
  target_id VARCHAR(64) NOT NULL,
  detail TEXT NOT NULL,
  created_at VARCHAR(32) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS project_modules (
  id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  name VARCHAR(120) NOT NULL,
  description TEXT NOT NULL,
  lead_id VARCHAR(64),
  state VARCHAR(20) NOT NULL,
  start_date VARCHAR(32) NOT NULL,
  end_date VARCHAR(32) NOT NULL,
  version INTEGER NOT NULL DEFAULT 1,
  archived_at VARCHAR(32),
  created_at VARCHAR(32) NOT NULL,
  updated_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(project_id) REFERENCES projects(id),
  FOREIGN KEY(lead_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS module_issues (
  workspace_id VARCHAR(64) NOT NULL,
  module_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  added_at VARCHAR(32) NOT NULL,
  PRIMARY KEY(module_id,issue_id),
  FOREIGN KEY(module_id) REFERENCES project_modules(id),
  FOREIGN KEY(issue_id) REFERENCES issues(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS planning_baselines (
  issue_id VARCHAR(64) PRIMARY KEY,
  workspace_id VARCHAR(64) NOT NULL,
  project_id VARCHAR(64) NOT NULL,
  sprint_id VARCHAR(64),
  status_id VARCHAR(64) NOT NULL,
  story_points INTEGER NOT NULL,
  deleted_at VARCHAR(32),
  recorded_at VARCHAR(32) NOT NULL,
  FOREIGN KEY(issue_id) REFERENCES issues(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS sprint_snapshots (
  sprint_id VARCHAR(64) NOT NULL,
  phase VARCHAR(10) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  total_issues INTEGER NOT NULL,
  completed_issues INTEGER NOT NULL,
  total_points INTEGER NOT NULL,
  completed_points INTEGER NOT NULL,
  recorded_at VARCHAR(32) NOT NULL,
  PRIMARY KEY(sprint_id,phase),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS sprint_issue_snapshots (
  sprint_id VARCHAR(64) NOT NULL,
  phase VARCHAR(10) NOT NULL,
  workspace_id VARCHAR(64) NOT NULL,
  issue_id VARCHAR(64) NOT NULL,
  issue_key VARCHAR(32) NOT NULL,
  summary VARCHAR(255) NOT NULL,
  status_id VARCHAR(64) NOT NULL,
  story_points INTEGER NOT NULL,
  category VARCHAR(20) NOT NULL,
  PRIMARY KEY(sprint_id,phase,issue_id),
  FOREIGN KEY(sprint_id) REFERENCES sprints(id),
  FOREIGN KEY(issue_id) REFERENCES issues(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX issues_workspace_project ON issues (workspace_id,project_id,deleted_at);
CREATE INDEX issues_assignee ON issues (workspace_id,assignee_id);
CREATE INDEX issues_sprint ON issues (sprint_id,status_id);
CREATE INDEX history_workspace_created ON history (workspace_id,created_at);
CREATE INDEX notifications_user ON notifications (workspace_id,user_id,read_at);
CREATE INDEX sessions_expiry ON sessions (expires_at);
CREATE INDEX modules_workspace_project ON project_modules (workspace_id,project_id,archived_at);
CREATE INDEX module_issues_issue ON module_issues (workspace_id,issue_id);
CREATE INDEX planning_baselines_project ON planning_baselines (workspace_id,project_id);
CREATE INDEX sprint_snapshots_workspace ON sprint_snapshots (workspace_id,sprint_id);
